def transform(grid):
    out = [row[:] for row in grid]
    color = next((v for row in grid for v in row if v not in (0,)), None)
    for i, row in enumerate(grid):
        if row[-1] == 0 and color is not None and color in row:
            last = max(j for j, v in enumerate(row) if v == color)
            for j in range(last + 1, len(row)):
                out[i][j] = 1
    return out
